func:
// The line view's only door to the database (ADR-0027): the role
// ofm_screens, which can call the functions of migration 018 and nothing
// else. Inputs (msg.topic):
// - "load": the model (config.fn_screen_model) and each line's stops to
//   code (hist.fn_screen_stops_to_code, last 24 hours); at start, every
//   30 s, and after every action
// - "status": every 10 s, each line in its schedule now? the next scheduled
//   start; the running order's good units (hist.fn_screen_line_status)
// - "signin" / "setpin" {req}: config.fn_person_sign_in / _set_pin
// - "action" {req}: start, startnew, changeoverdone, complete, code, as the
//   signed-in person (config.fn_person_*)
// Outputs: 1 to the hub: "model", "stops", "status", "result" {req, payload};
// 2 "load" back to this node after a successful action.
const STOP_HOURS = 24;
const pg = global.get("pg");
if (!pg) { node.error("the pg library is not available (see nodered/settings.js)"); return null; }
let pool = context.get("pool");
if (!pool) {
    pool = new pg.Pool({
        host: "timescaledb", port: 5432, database: "ofm", user: "ofm_screens", password: env.get("OFM_SCREENS_DB_PASSWORD"),
        application_name: "ofm-screens", max: 3, connectionTimeoutMillis: 5000, statement_timeout: 20000
    });
    pool.on("error", () => { /* reconnects on the next query */ });
    context.set("pool", pool);
}
const req = msg.req || {};

if (msg.topic === "load") {
    if (context.get("loading")) return null;
    context.set("loading", true);
    try {
        const lines = (await pool.query("SELECT config.fn_screen_model() AS m")).rows[0].m || [];
        const stops = {};
        for (const l of lines) {
            stops[l.id] = (await pool.query(
                "SELECT machine_id, machine_display_name, event_ts::text AS event_ts, extract(epoch FROM event_ts) * 1000 AS event_ms, " +
                "state, fault_code, extract(epoch FROM uncoded_from) * 1000 AS from_ms, uncoded_s, stop_s " +
                "FROM hist.fn_screen_stops_to_code($1, $2)", [l.id, STOP_HOURS])).rows
                .filter(r => r.uncoded_s >= 1)               // a stop's last fraction of a second is not worth coding
                .map(r => ({ machineId: r.machine_id, machineName: r.machine_display_name, eventTs: r.event_ts,
                             eventMs: Math.round(Number(r.event_ms)), state: r.state, faultCode: r.fault_code,
                             fromMs: Math.round(Number(r.from_ms)), uncodedS: Math.round(r.uncoded_s), stopS: Math.round(r.stop_s) }));
        }
        node.status({ fill: "green", shape: "dot", text: lines.length + " line(s), " +
                      Object.values(stops).reduce((n, s) => n + s.length, 0) + " stop(s) to code · " + new Date().toLocaleTimeString() });
        return [[{ topic: "model", payload: lines }, { topic: "stops", payload: stops }], null];
    } catch (e) {
        node.status({ fill: "red", shape: "ring", text: "cannot read the model: " + e.message });
        return null;
    } finally {
        context.set("loading", false);
    }
}

if (msg.topic === "status") {                                // every 10 s: in schedule now? the order's progress
    try {
        const r = (await pool.query("SELECT hist.fn_screen_line_status() AS s")).rows[0].s || {};
        return [{ topic: "status", payload: r }, null];
    } catch (e) {
        return null;                                              // the next load shows the database problem
    }
}

if (msg.topic === "signin" || msg.topic === "setpin") {
    try {
        const r = (await pool.query(msg.topic === "signin"
            ? "SELECT result, person_id, display_name, extract(epoch FROM retry_at) * 1000 AS retry_at FROM config.fn_person_sign_in($1, $2, $3)"
            : "SELECT result, person_id, display_name, NULL AS retry_at FROM config.fn_person_set_pin($1, $2, $3)",
            [req.employeeNo, req.pin, req.screen])).rows[0];
        if (r.retry_at !== null) r.retry_at = Math.round(Number(r.retry_at));
        return [{ topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd, employeeNo: req.employeeNo }, payload: r }, null];
    } catch (e) {
        return [{ topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd }, payload: { result: "error", error: e.message } }, null];
    }
}

if (msg.topic === "action") {
    const calls = {
        start:          ["SELECT config.fn_person_work_order_start($1, $2)", [req.personId, req.workOrderId]],
        startnew:       ["SELECT config.fn_person_work_order_start_new($1, $2, $3, $4)", [req.personId, req.lineId, req.sku, req.qty]],
        changeoverdone: ["SELECT config.fn_person_work_order_changeover_end($1, $2)", [req.personId, req.workOrderId]],
        complete:       ["SELECT config.fn_person_work_order_complete($1, $2)", [req.personId, req.workOrderId]],
        code:           ["SELECT config.fn_person_assign_reason($1, $2, $3::timestamptz, $4, $5)",
                         [req.personId, req.machineId, req.eventTs, req.reasonCode, req.comment]]
    };
    const c = calls[req.cmd];
    if (!c) return null;
    const out = { topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd }, payload: {} };
    try {
        await pool.query(c[0], c[1]);
    } catch (e) {
        out.payload.error = e.code === "42501" ? "Sign in again: " + e.message : e.message;
    }
    return [out, out.payload.error ? null : { topic: "load" }];    // after a change, every screen shows it at once
}
return null;

// Connects the line view to the UNS as the read-only MQTT user and keeps
// its subscriptions equal to what the lines need (from the hub): each
// line's .../workorder and .../kpi/+, each machine's .../state and its
// fault code. Output: control messages for the "mqtt in" node.
// The password comes from deploy/.env, so nothing secret is in the flow file.
const want = Array.isArray(msg.payload) ? msg.payload : [];
const had = context.get("topics") || [];
const out = [];
if (!context.get("connected")) {
    out.push({ action: "connect", broker: {
        broker: "mosquitto", port: 1883, clientid: "ofm-screens-" + Math.random().toString(16).slice(2, 8),
        username: "ofm_reader", password: env.get("OFM_MQTT_READER_PASSWORD")
    } });
    context.set("connected", true);
}
const gone = had.filter(t => !want.includes(t));
const added = want.filter(t => !had.includes(t));
if (gone.length) out.push({ action: "unsubscribe", topic: gone });
if (added.length) out.push({ action: "subscribe", topic: added.map(t => ({ topic: t, qos: 1 })) });
context.set("topics", want);
node.status({ fill: "green", shape: "dot", text: want.length + " topics" });
return out.length ? [out] : null;

// Line view hub (ADR-0027, ADR-0028, step 3a.8). Holds what every screen
// shows and who is signed in where; it never touches the database itself.
// Inputs (msg.topic):
// - "model"   the lines from config.fn_screen_model() (node "database")
// - "stops"   {lineId: [stops to code]} (node "database")
// - "status"  {lineId: {scheduled, nextScheduledMs, order: {workOrderId, plannedQty, good, reachedMs,
//             goodTopic, counterValue, counterMinuteMs}}}: the running order's good
//             counter is subscribed to as well, for live progress (migration 029)
// - "result"  the answer to a sign-in or an action (node "database")
// - "tick"    every second: sessions untouched for OFM_SCREEN_IDLE_MINUTES
//             are signed out; every screen gets the current picture
// - a UNS topic: a live value (msg.payload; "" = topic cleared)
// - from the line view (msg._client = the browser): {cmd, ...}
//   hello, touch, signin, setpin, signout, start, startnew, changeoverdone,
//   complete, code
// A person is signed in on one browser page, never on others; a reload or a
// new browser asks again. The page names itself with a random screenId on
// every message, so a sign-in survives the page's connection being
// re-established (Wi-Fi, a tab in the background); answers go to the
// page's current connection (socket).
// Outputs: 1 line view (with msg._client: that browser only); 2 database
// requests; 3 the topics to subscribe to (node "UNS").
const IDLE_MS = Math.max(1, Number(env.get("OFM_SCREEN_IDLE_MINUTES")) || 5) * 60000;
const now = Date.now();
const st = context.get("st") || { lines: [], live: {}, stops: {}, sessions: {} };
context.set("st", st);
const toView = [], toDb = [];
let subscribe = null;

const client = msg._client && msg._client.socketId ? msg._client : null;
const reply = (topic, payload) => toView.push({ topic, payload, _client: client });
const notice = (text, kind) => {                          // cmd: which action it answers
    const cmd = msg.payload && msg.payload.cmd || null;
    if (kind === "error") node.warn("refused " + cmd + ": " + text);      // shows in: docker compose logs screens
    reply("notice", { text, kind: kind || "info", at: now, cmd });
};
const screenId = client ? String(msg.payload && msg.payload.screenId || client.socketId) : null;
const sessionOf = () => {
    const s = screenId && st.sessions[screenId];
    if (s) s.socketId = client.socketId;                  // the page's current connection
    return s;
};
const sessionView = s => s ? { signedIn: true, name: s.name, personId: s.personId, expiresAt: s.last + IDLE_MS }
                           : { signedIn: false };

if (msg.topic === "model") {
    st.lines = Array.isArray(msg.payload) ? msg.payload : [];
    resubscribe();
} else if (msg.topic === "stops") {
    st.stops = msg.payload || {};
} else if (msg.topic === "status") {
    st.status = msg.payload || {};
    const was = (st.goodTopics || []).join();
    st.goodTopics = goodTopics();
    if (st.goodTopics.join() !== was) resubscribe();       // a new order, or its counter changed
} else if (msg.topic === "tick") {
    for (const [id, s] of Object.entries(st.sessions)) {
        if (now - s.last > IDLE_MS) {
            delete st.sessions[id];
            toView.push({ topic: "session", payload: { signedIn: false, why: "idle" }, _client: { socketId: s.socketId } });
        }
    }
    toView.push({ topic: "picture", payload: picture() });
} else if (msg.topic === "result") {
    result(msg.req || {}, msg.payload || {});
} else if (client && msg.payload && typeof msg.payload === "object" && msg.payload.cmd) {
    fromScreen(msg.payload);
} else if (typeof msg.topic === "string" && msg.topic.split("/").length >= 5) {
    let v = msg.payload;
    if (typeof v === "string" && v !== "") { try { v = JSON.parse(v); } catch (e) { /* keep as text */ } }
    if (v === "" || v === null || v === undefined) delete st.live[msg.topic];
    else st.live[msg.topic] = v;
}

node.status({ fill: "green", shape: "dot", text: st.lines.length + " line(s), " + Object.keys(st.sessions).length + " signed in" });
return [toView.length ? toView : null, toDb.length ? toDb : null, subscribe];

// The topics every screen needs: each line's order and KPIs, each machine's
// state and fault code, and each running order's good counter.
function resubscribe() {
    const topics = [];
    for (const l of st.lines) {
        topics.push(l.topic + "/workorder", l.topic + "/kpi/+");
        for (const m of l.machines) {
            topics.push(m.topic + "/state");
            if (m.faultTopic) topics.push(m.faultTopic);
        }
    }
    for (const t of st.goodTopics || []) if (!topics.includes(t)) topics.push(t);
    for (const t of Object.keys(st.live)) {                // forget values of topics no longer shown
        if (!topics.some(p => matches(p, t))) delete st.live[t];
    }
    subscribe = { topic: "subscribe", payload: topics.sort() };
}
function goodTopics() {
    const out = [];
    for (const v of Object.values(st.status || {})) {
        const t = v && v.order && v.order.goodTopic;
        if (typeof t === "string" && t.split("/").length >= 6 && !out.includes(t)) out.push(t);
    }
    return out.sort();
}

function fromScreen(p) {
    const s = sessionOf();
    if (p.cmd === "hello") {
        reply("session", sessionView(s));
        reply("picture", picture());
        return;
    }
    if (p.cmd === "touch") {
        if (s) s.last = now;
        reply("session", sessionView(s));
        return;
    }
    if (p.cmd === "signout") {
        delete st.sessions[screenId];
        reply("session", { signedIn: false, why: "signout" });
        return;
    }
    if (p.cmd === "signin" || p.cmd === "setpin") {
        const employeeNo = String(p.employeeNo || "").trim();
        const pin = String(p.pin || "");
        if (!employeeNo) { notice("Type your employee number.", "error"); return; }
        if (p.cmd === "setpin" && !/^[0-9]{4,8}$/.test(pin)) { notice("A PIN is 4 to 8 digits.", "error"); return; }
        toDb.push({ topic: p.cmd, req: { socketId: client.socketId, screenId, cmd: p.cmd, employeeNo, pin, screen: screenName() } });
        return;
    }
    // everything else changes something: only for a signed-in person
    if (!s) {
        reply("session", { signedIn: false, why: "required" });
        notice("Sign in first.", "error");
        return;
    }
    s.last = now;
    const line = st.lines.find(l => l.id === Number(p.lineId));
    if (!line) { notice("Unknown line.", "error"); return; }
    const req = { socketId: client.socketId, screenId, personId: s.personId, cmd: p.cmd, lineId: line.id };
    if (p.cmd === "start") {
        req.workOrderId = Number(p.workOrderId);
        if (!line.plannedOrders.some(o => o.id === req.workOrderId)) { notice("That order is not planned on this line any more.", "error"); return; }
    } else if (p.cmd === "startnew") {
        req.sku = String(p.sku || "");
        req.qty = Math.round(Number(p.qty));
        if (!line.products.some(x => x.sku === req.sku) || !(req.qty > 0)) { notice("Choose a product and a quantity above 0.", "error"); return; }
    } else if (p.cmd === "changeoverdone" || p.cmd === "complete") {
        const wo = st.live[line.topic + "/workorder"];
        if (!wo || !wo.active || wo.workOrderId !== Number(p.workOrderId)) { notice("That order is not running any more.", "error"); return; }
        req.workOrderId = wo.workOrderId;
    } else if (p.cmd === "code") {
        req.machineId = Number(p.machineId);
        req.eventTs = String(p.eventTs || "");                // the event's exact time, as the database wrote it
        req.reasonCode = String(p.reasonCode || "");
        req.comment = p.comment ? String(p.comment).slice(0, 500) : null;
        const reason = line.reasons.find(r => r.code === req.reasonCode);
        if (!reason || (reason.machineId !== null && reason.machineId !== req.machineId) ||
            !(st.stops[line.id] || []).some(x => x.machineId === req.machineId && x.eventTs === req.eventTs)) {
            notice("Choose a reason for one of the stops in the list.", "error");
            return;
        }
    } else {
        node.warn("ignored: " + JSON.stringify(p));
        return;
    }
    toDb.push({ topic: "action", req });
}

function result(req, r) {
    const c = req.socketId ? { socketId: req.socketId } : null;
    const say = (text, kind) => {
        if (kind === "error") node.warn("refused " + req.cmd + ": " + text);
        toView.push({ topic: "notice", payload: { text, kind: kind || "info", at: now, cmd: req.cmd || null }, _client: c });
    };
    if (req.cmd === "signin" || req.cmd === "setpin") {
        if (r.result === "ok" || r.result === "pin_set") {
            const id = req.screenId || req.socketId;
            for (const [other, s] of Object.entries(st.sessions)) {   // one browser page per person
                if (s.personId === r.person_id && other !== id) {
                    delete st.sessions[other];
                    toView.push({ topic: "session", payload: { signedIn: false, why: "elsewhere" }, _client: { socketId: s.socketId } });
                }
            }
            st.sessions[id] = { personId: r.person_id, name: r.display_name, employeeNo: req.employeeNo, last: now, socketId: req.socketId };
            toView.push({ topic: "session", payload: sessionView(st.sessions[id]), _client: c });
            say((r.result === "pin_set" ? "PIN saved. " : "") + "Signed in as " + r.display_name + ".", "ok");
        } else if (r.result === "no_pin") {
            toView.push({ topic: "session", payload: { signedIn: false, choosePin: true, employeeNo: req.employeeNo }, _client: c });
            say("First sign-in: choose a PIN of 4 to 8 digits.");
        } else {
            const text = {
                wrong_pin: "Wrong employee number or PIN.",
                unknown_person: "Wrong employee number or PIN.",
                locked: "Too many wrong PINs: try again at " + (r.retry_at ? new Date(r.retry_at).toTimeString().slice(0, 5) : "later") + ".",
                bad_pin: "A PIN is 4 to 8 digits.",
                pin_exists: "This person already has a PIN: sign in with it.",
                error: "Cannot reach the database: " + (r.error || "")
            }[r.result] || "Sign-in failed (" + r.result + ").";
            say(text, "error");
        }
        return;
    }
    if (r.error) {
        say(r.error, "error");
        return;
    }
    const done = { start: "Order started.", startnew: "Order started.", changeoverdone: "Changeover done.",
                   complete: "Order complete.", code: "Stop coded." }[req.cmd] || "Done.";
    say(done, "ok");
}

// What every screen shows: the lines, each with its live values.
function picture() {
    return {
        serverTime: now,
        lines: st.lines.map(l => ({
            id: l.id, name: l.name, displayName: l.displayName, minorStopS: l.minorStopS, orderRequired: l.orderRequired,
            machines: l.machines.map(m => ({
                id: m.id, name: m.name, displayName: m.displayName, isConstraint: m.isConstraint, isOutput: m.isOutput,
                state: st.live[m.topic + "/state"] || null,
                fault: m.faultTopic ? st.live[m.faultTopic] || null : null
            })),
            workorder: st.live[l.topic + "/workorder"] || null,
            kpi: { hour: st.live[l.topic + "/kpi/hour"] || null, day: st.live[l.topic + "/kpi/day"] || null,
                   order: st.live[l.topic + "/kpi/order"] || null },
            stops: st.stops[l.id] || [],
            status: (st.status || {})[l.id] || null,
            counter: counterOf(l.id),                      // the running order's good counter, live
            reasons: l.reasons, products: l.products, plannedOrders: l.plannedOrders
        }))
    };
}
function counterOf(lineId) {
    const o = st.status && st.status[lineId] && st.status[lineId].order;
    const v = o && o.goodTopic ? st.live[o.goodTopic] : null;
    return v && typeof v === "object" && typeof v.v === "number" ? { v: v.v, ts: v.ts, q: v.q } : null;
}
function screenName() {
    const h = client && client.socketIp ? client.socketIp : null;
    return h ? String(h).slice(0, 64) : null;
}
function matches(pattern, topic) {
    const p = pattern.split("/"), t = topic.split("/");
    if (p.length !== t.length) return false;
    return p.every((x, i) => x === "+" || x === t[i]);
}

// OFM Trend (ADR-0029, step H1): answers the trend page. Like the line
// view it reads the database only as ofm_screens, through the functions of
// migration 023. Messages from the page (msg._client = that browser):
// - {cmd: "tags"}       the historised numeric signals (config.fn_trend_tags)
// - {cmd: "historian"}  per signal: last value, values in 24 h, stored since
// - {cmd: "data", req, from, to, points, pens: [{key, id, shift}], bands: {states, orders, shifts}, machines, lines}
//                       per pen the values (hist.fn_trend_data) and the
//                       statistics (hist.fn_trend_stats) of [from, to)
// - {cmd: "periods", lines}  the lines' recent orders and shifts, to choose as the period
// - {cmd: "stats", req, from, to, pens}
//                       the statistics only, for the span between the
//                       cursors A and B (the same function)
// Annotations (step H2a, ADR-0031), as a signed-in person (ADR-0028):
// - {cmd: "hello", screenId}            the page's session and the kinds of note
// - {cmd: "signin" | "setpin", screenId, employeeNo, pin}
// - {cmd: "signout" | "touch", screenId} sign out / still at the desk
// - {cmd: "annotate", screenId, ts, tsEnd, scope, targetId, categoryId, text, replaces}
// - {cmd: "unannotate", screenId, id, reason}
// "data" also returns the annotations of the pens, their machines and lines.
// A session belongs to one page (screenId, random per browser tab) and ends
// after OFM_TREND_IDLE_MINUTES (default 30) without a touch.
// Answers go back to that browser only: {topic, payload}. Times are epoch
// milliseconds UTC (ADR-0003).
const MAX_PENS = 16;
const IDLE_MS = Math.max(1, Number(env.get("OFM_TREND_IDLE_MINUTES")) || 30) * 60000;
const pg = global.get("pg");
if (!pg) { node.error("the pg library is not available (see nodered/settings.js)"); return null; }
let pool = context.get("pool");
if (!pool) {
    pool = new pg.Pool({
        host: "timescaledb", port: 5432, database: "ofm", user: "ofm_screens", password: env.get("OFM_SCREENS_DB_PASSWORD"),
        application_name: "ofm-trend", max: 6, connectionTimeoutMillis: 5000, statement_timeout: 30000
    });
    pool.on("error", () => { /* reconnects on the next query */ });
    context.set("pool", pool);
}
const client = msg._client && msg._client.socketId ? msg._client : null;
const p = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
if (!client || !p.cmd) return null;
const reply = (topic, payload) => node.send({ topic, payload, _client: client });
const num = x => x === null || x === undefined ? null : Number(x);
const now = Date.now();
const sessions = context.get("sessions") || {};
for (const [id, s] of Object.entries(sessions)) if (now - s.last > IDLE_MS) delete sessions[id];
context.set("sessions", sessions);
const screenId = typeof p.screenId === "string" && /^[A-Za-z0-9_-]{8,64}$/.test(p.screenId) ? p.screenId : null;
const session = screenId ? sessions[screenId] : null;
const sessionView = s => s ? { signedIn: true, name: s.name, expiresAt: s.last + IDLE_MS } : { signedIn: false };
const notice = (text, kind, cmd) => reply("notice", { text, kind: kind || "info", cmd: cmd || p.cmd, at: now });
const iso = ms => Number.isFinite(Number(ms)) ? new Date(Number(ms)).toISOString() : null;

try {
    if (p.cmd === "tags") {
        const tags = (await pool.query("SELECT config.fn_trend_tags() AS t")).rows[0].t || [];
        node.status({ fill: "green", shape: "dot", text: tags.length + " signal(s) · " + new Date().toLocaleTimeString() });
        reply("tags", tags);
    } else if (p.cmd === "historian") {
        const rows = (await pool.query("SELECT * FROM hist.fn_historian_tags()")).rows;
        reply("historian", rows.map(r => ({ id: r.property_id, lastMs: num(r.last_ms), lastValue: num(r.last_value), lastQuality: r.last_quality,
                                            values24h: num(r.values_24h), sinceMs: num(r.since_ms) })));
    } else if (p.cmd === "hello") {
        const cats = (await pool.query("SELECT config.fn_annotation_categories() AS c")).rows[0].c || [];
        reply("categories", cats);
        reply("session", sessionView(session));
    } else if (p.cmd === "touch") {
        if (session) session.last = now;
        reply("session", sessionView(session));
    } else if (p.cmd === "signout") {
        if (screenId) delete sessions[screenId];
        reply("session", { signedIn: false, why: "signout" });
    } else if (p.cmd === "signin" || p.cmd === "setpin") {
        const employeeNo = String(p.employeeNo || "").trim(), pin = String(p.pin || "");
        if (!screenId) throw new Error("the page has no screen id: reload it");
        if (!employeeNo) { notice("Type your employee number.", "error"); return null; }
        if (p.cmd === "setpin" && !/^[0-9]{4,8}$/.test(pin)) { notice("A PIN is 4 to 8 digits.", "error"); return null; }
        const r = (await pool.query(p.cmd === "signin"
            ? "SELECT result, person_id, display_name, extract(epoch FROM retry_at) * 1000 AS retry_at FROM config.fn_person_sign_in($1, $2, $3)"
            : "SELECT result, person_id, display_name, NULL AS retry_at FROM config.fn_person_set_pin($1, $2, $3)",
            [employeeNo, pin, "trend"])).rows[0];
        if (r.result === "ok" || r.result === "pin_set") {
            sessions[screenId] = { personId: r.person_id, name: r.display_name, last: now };
            reply("session", sessionView(sessions[screenId]));
            notice((r.result === "pin_set" ? "PIN saved. " : "") + "Signed in as " + r.display_name + ".", "ok");
        } else if (r.result === "no_pin") {
            reply("session", { signedIn: false, choosePin: true, employeeNo });
            notice("First sign-in: choose a PIN of 4 to 8 digits.");
        } else {
            notice({ wrong_pin: "Wrong employee number or PIN.", unknown_person: "Wrong employee number or PIN.",
                     locked: "Too many wrong PINs: try again at " + (r.retry_at ? new Date(Number(r.retry_at)).toTimeString().slice(0, 5) : "later") + ".",
                     bad_pin: "A PIN is 4 to 8 digits.", pin_exists: "This person already has a PIN: sign in with it." }[r.result] || r.result, "error");
        }
    } else if (p.cmd === "annotate" || p.cmd === "unannotate") {
        if (!session) {
            reply("session", { signedIn: false, why: "required" });
            notice("Sign in to annotate.", "error");
            return null;
        }
        session.last = now;
        if (p.cmd === "annotate") {
            const text = String(p.text || "").trim();
            if (!text) { notice("Type the annotation.", "error"); return null; }
            if (text.length > 500) { notice("At most 500 characters.", "error"); return null; }
            const id = (await pool.query("SELECT config.fn_person_annotate($1, $2, $3, $4, $5, $6, $7, $8) AS id",
                [session.personId, iso(p.ts), p.tsEnd ? iso(p.tsEnd) : null, String(p.scope || ""), Number(p.targetId),
                 Number(p.categoryId), text, p.replaces ? Number(p.replaces) : null])).rows[0].id;
            reply("annotated", { id: Number(id), replaces: p.replaces || null });
            notice(p.replaces ? "Annotation corrected." : "Annotation saved.", "ok");
        } else {
            await pool.query("SELECT config.fn_person_annotation_remove($1, $2, $3)", [session.personId, Number(p.id), p.reason ? String(p.reason) : null]);
            reply("annotated", { removed: Number(p.id) });
            notice("Annotation removed.", "ok");
        }
        reply("session", sessionView(session));
    } else if (p.cmd === "periods") {
        // the lines' recent orders and the shifts of the last 14 days, to choose one as the period
        const lines = (Array.isArray(p.lines) ? p.lines : []).map(Number).filter(x => Number.isInteger(x) && x > 0).slice(0, 4);
        const orders = lines.length ? (await pool.query("SELECT * FROM hist.fn_trend_order_list($1, 60)", [lines])).rows.map(o => ({
            lineId: o.line_id, id: o.work_order_id, number: o.wo_number, sku: o.sku, t0: Number(o.t0_ms), t1: Number(o.t1_ms), running: o.running })) : [];
        const shifts = lines.length ? (await pool.query(
            "SELECT line_id, name, shift_day::text AS day, t0_ms, t1_ms FROM hist.fn_trend_shifts($1::integer[], now() - interval '14 days', now())", [lines]))
            .rows.map(x => ({ lineId: x.line_id, name: x.name, day: x.day, t0: Number(x.t0_ms), t1: Number(x.t1_ms) })) : [];
        shifts.sort((a, b) => b.t0 - a.t0);
        reply("periods", { orders, shifts: shifts.slice(0, 100) });
    } else if (p.cmd === "data" || p.cmd === "stats") {
        const from = Number(p.from), to = Number(p.to);
        const points = Math.min(Math.max(Math.round(Number(p.points) || 1000), 100), 4000);
        const YEARS20 = 20 * 365 * 86400000;
        // a pen: a signal, perhaps shifted in time (step H2b: compare): its values come from
        // [from - shift, to - shift) and are drawn shift later. Old pages send plain IDs.
        const pens = (Array.isArray(p.pens) ? p.pens : []).map(x => typeof x === "object" && x
            ? { key: String(x.key || x.id), id: Number(x.id), shift: Math.round(Number(x.shift) || 0) }
            : { key: String(x), id: Number(x), shift: 0 })
            .filter(x => Number.isInteger(x.id) && x.id > 0 && Math.abs(x.shift) <= YEARS20 && /^[0-9a-z:_-]{1,40}$/i.test(x.key)).slice(0, MAX_PENS);
        if (!(from < to) || !Number.isFinite(from) || !Number.isFinite(to)) throw new Error("the period is not valid");
        const started = Date.now();
        const iso = ms => new Date(ms).toISOString();
        const f = iso(from), t = iso(to);
        const series = {}, stats = {};
        const statsOf = x => x ? { source: x.source, n: num(x.n), min: num(x.v_min), max: num(x.v_max), avg: num(x.v_avg),
                                   covered: num(x.s_covered), aboveHi: num(x.s_above_hi), aboveHiHi: num(x.s_above_hihi),
                                   belowLo: num(x.s_below_lo), belowLoLo: num(x.s_below_lolo) } : null;
        if (p.cmd === "stats") {
            await Promise.all(pens.map(async x => {
                stats[x.key] = statsOf((await pool.query("SELECT * FROM hist.fn_trend_stats($1, $2, $3)", [x.id, iso(from - x.shift), iso(to - x.shift)])).rows[0]);
            }));
            reply("stats", { req: p.req, from, to, stats });
            return null;
        }
        const ids = [...new Set(pens.map(x => x.id))];
        const annotations = ids.length ? (await pool.query("SELECT * FROM hist.fn_trend_annotations($1, $2, $3)", [ids, f, t])).rows.map(a => ({
            id: Number(a.id), ts: Number(a.ts_ms), tsEnd: num(a.ts_end_ms), scope: a.scope, scopeName: a.scope_name, propertyId: a.property_id,
            machineId: a.machine_id, lineId: a.line_id, category: a.category, categoryName: a.category_name, colour: a.colour, text: a.text,
            person: a.person, created: Number(a.created_ms), corrected: a.corrected })) : [];
        await Promise.all(pens.map(async x => {
            const [d, s] = await Promise.all([
                pool.query("SELECT t_ms, v, v_min, v_max, q, source, bucket_s FROM hist.fn_trend_data($1, $2, $3, $4)", [x.id, iso(from - x.shift), iso(to - x.shift), points]),
                pool.query("SELECT * FROM hist.fn_trend_stats($1, $2, $3)", [x.id, iso(from - x.shift), iso(to - x.shift)])
            ]);
            const rows = d.rows;
            series[x.key] = {
                source: rows.length ? rows[0].source : null,
                bucketS: rows.length ? rows[0].bucket_s : null,
                shift: x.shift,
                // [t, v, min, max, q]: compact for the socket; t already moved by the shift
                rows: rows.map(r => [Number(r.t_ms) + x.shift, num(r.v), num(r.v_min), num(r.v_max), r.q])
            };
            stats[x.key] = statsOf(s.rows[0]);
        }));
        // bands under the trend (step H2b): machine states, orders, shifts
        const want = p.bands && typeof p.bands === "object" ? p.bands : {};
        const machines = (Array.isArray(p.machines) ? p.machines : []).map(Number).filter(x => Number.isInteger(x) && x > 0).slice(0, 6);
        const lines = (Array.isArray(p.lines) ? p.lines : []).map(Number).filter(x => Number.isInteger(x) && x > 0).slice(0, 4);
        const bands = {};
        if (want.states && machines.length) {
            bands.states = (await pool.query("SELECT * FROM hist.fn_trend_states($1, $2, $3, $4)", [machines, f, t, points])).rows.map(r =>
                [r.machine_id, Number(r.t0_ms), Number(r.t1_ms), r.state, r.state_name, r.colour, r.reason, r.dominant]);
        }
        if (want.orders && lines.length) {
            bands.orders = (await pool.query("SELECT * FROM hist.fn_trend_orders($1, $2, $3)", [lines, f, t])).rows.map(r =>
                ({ lineId: r.line_id, id: r.work_order_id, number: r.wo_number, sku: r.sku, t0: Number(r.t0_ms), setupEnd: num(r.setup_end_ms), t1: Number(r.t1_ms), running: r.running }));
        }
        if (want.shifts && lines.length) {
            bands.shifts = (await pool.query("SELECT line_id, name, t0_ms, t1_ms FROM hist.fn_trend_shifts($1::integer[], $2, $3)", [lines, f, t]))
                .rows.map(x => ({ lineId: x.line_id, name: x.name, t0: Number(x.t0_ms), t1: Number(x.t1_ms) }));
        }
        const ms = Date.now() - started;
        node.status({ fill: "green", shape: "dot", text: pens.length + " pen(s), " + Object.values(series).reduce((n, s) => n + s.rows.length, 0) + " points, " + ms + " ms" });
        reply("data", { req: p.req, from, to, ms, series, stats, annotations, bands });
    }
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: e.message });
    if (p.cmd === "annotate" || p.cmd === "unannotate") notice("Not saved: " + e.message, "error");
    else reply("error", { req: p.req, cmd: p.cmd, text: e.message });
}
return null;

// OFM Trend: CSV export (ADR-0029, step H1). GET /trend/export with
//   pens=1,2,3  from=<epoch ms>  to=<epoch ms>  mode=raw|shown  points=<n>
// mode=raw ("as stored"): every stored value, signal by signal, with local
//   time (site), UTC epoch ms, topic, name, value, unit, quality; read in
//   pages of 50,000 and sent as they come, at most 1,000,000 values.
// mode=shown ("as shown"): one row per interval of the chart (the same
//   interval for all pens): local time, UTC ms, then per pen its average,
//   minimum and maximum.
// The file is written straight to the browser's connection as it is read,
// so a large export never sits in memory. Role ofm_screens, functions of
// migration 023 only.
const MAX_RAW = 1000000, PAGE = 50000, MAX_PENS = 16;
const pg = global.get("pg");
const res = msg.res && msg.res._res;
if (!pg || !res) return null;
let pool = context.get("pool");
if (!pool) {
    pool = new pg.Pool({
        host: "timescaledb", port: 5432, database: "ofm", user: "ofm_screens", password: env.get("OFM_SCREENS_DB_PASSWORD"),
        application_name: "ofm-trend-export", max: 2, connectionTimeoutMillis: 5000, statement_timeout: 120000
    });
    pool.on("error", () => { /* reconnects on the next query */ });
    context.set("pool", pool);
}
const q = msg.req.query || {};
const pens = String(q.pens || "").split(",").map(Number).filter(x => Number.isInteger(x) && x > 0).slice(0, MAX_PENS);
const from = Number(q.from), to = Number(q.to);
const mode = q.mode === "shown" ? "shown" : "raw";
const points = Math.min(Math.max(Math.round(Number(q.points) || 1000), 100), 4000);
const fail = (code, text) => { res.status(code).type("text/plain").send(text); return null; };
if (!pens.length || !Number.isFinite(from) || !Number.isFinite(to) || !(from < to)) return fail(400, "pens, from and to are needed (from before to)");

const two = n => String(n).padStart(2, "0");               // local time of the server (TZ of the container)
const stamp = d => d.getFullYear() + two(d.getMonth() + 1) + two(d.getDate()) + "-" + two(d.getHours()) + two(d.getMinutes());
const name = "ofm-trend-" + stamp(new Date(from)) + "-to-" + stamp(new Date(to)) + (mode === "raw" ? "-raw" : "-shown") + ".csv";
const f = new Date(from).toISOString(), t = new Date(to).toISOString();
const csvText = s => '"' + String(s === null || s === undefined ? "" : s).replace(/"/g, '""') + '"';
let sent = 0;
try {
    if (mode === "raw") {
        res.status(200).set({ "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": 'attachment; filename="' + name + '"', "Cache-Control": "no-store" });
        res.write("﻿local_time,utc_ms,topic,name,value,unit,quality\r\n");     // BOM: Excel reads UTF-8
        let afterId = null, afterTs = null;
        for (;;) {
            const r = (await pool.query("SELECT property_id, ts, csv FROM hist.fn_trend_export($1, $2, $3, $4, $5, $6)",
                                        [pens, f, t, afterId, afterTs, Math.min(PAGE, MAX_RAW - sent)])).rows;
            if (!r.length) break;
            res.write(r.map(x => x.csv).join("\r\n") + "\r\n");
            sent += r.length;
            afterId = r[r.length - 1].property_id;
            afterTs = r[r.length - 1].ts;
            if (sent >= MAX_RAW) {
                res.write("# stopped after " + MAX_RAW + " values: export a shorter period, or use 'CSV as shown'\r\n");
                break;
            }
            if (r.length < PAGE) break;
        }
        res.end();
    } else {
        const tags = ((await pool.query("SELECT config.fn_trend_tags() AS t")).rows[0].t || []).filter(x => pens.includes(x.id));
        const byId = Object.fromEntries(tags.map(x => [x.id, x]));
        const use = pens.filter(id => byId[id]);
        if (!use.length) return fail(404, "none of these signals is in the historian");
        const tz = byId[use[0]].timeZone;
        const bucket = (await pool.query("SELECT extract(epoch FROM hist.fn_trend_bucket($1, $2, $3))::integer AS s", [f, t, points])).rows[0].s;
        const cols = {};                                           // t -> [avg, min, max] per pen
        for (const id of use) {
            const r = (await pool.query("SELECT t_ms, v, v_min, v_max FROM hist.fn_trend_data($1, $2, $3, $4, make_interval(secs => $5))",
                                        [id, f, t, points, bucket])).rows;
            for (const x of r) {
                const k = Number(x.t_ms);
                (cols[k] || (cols[k] = {}))[id] = [x.v, x.v_min, x.v_max];
            }
        }
        const local = new Intl.DateTimeFormat("en-CA", { timeZone: tz, year: "numeric", month: "2-digit", day: "2-digit",
                                                         hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
        const fmt = ms => local.format(new Date(ms)).replace(", ", " ").replace(/^(\d{4}-\d{2}-\d{2}) 24:/, "$1 00:");
        res.status(200).set({ "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": 'attachment; filename="' + name + '"', "Cache-Control": "no-store" });
        const head = ["local_time (" + tz + ", interval start)", "utc_ms"];
        for (const id of use) {
            const x = byId[id], label = (x.lineName || x.line) + " · " + (x.machineName || x.machine) + " · " + x.displayName + (x.unit ? " [" + x.unit + "]" : "");
            head.push(csvText(label + " avg"), csvText(label + " min"), csvText(label + " max"));
        }
        res.write("﻿" + head.join(",") + "\r\n");
        const keys = Object.keys(cols).map(Number).sort((a, b) => a - b);
        const lines = [];
        for (const k of keys) {
            const row = [fmt(k), k];
            for (const id of use) {
                const v = cols[k][id];
                const n = x => x === null || x === undefined ? "" : Number(Number(x).toPrecision(7));   // 7 significant digits
                row.push(v ? n(v[0]) : "", v ? n(v[1]) : "", v ? n(v[2]) : "");
            }
            lines.push(row.join(","));
            sent++;
        }
        res.write(lines.join("\r\n") + (lines.length ? "\r\n" : ""));
        res.end();
    }
    node.status({ fill: "green", shape: "dot", text: mode + ": " + sent + " row(s), " + pens.length + " pen(s) · " + new Date().toLocaleTimeString() });
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: e.message });
    if (!res.headersSent) return fail(500, "export failed: " + e.message);
    res.end("\r\n# export failed: " + e.message + "\r\n");
}
return null;

// Serves the chart library of the trend page, Apache ECharts, from OFM's own
// image (ADR-0029): no internet needed. The file is found by settings.js
// (global "echartsFile") and kept in memory after the first request.
let body = context.get("body");
if (!body) {
    const fs = global.get("fs"), file = global.get("echartsFile");
    if (!fs || !file) {
        msg.statusCode = 500;
        msg.payload = "console.error('OFM: the chart library is not in this image (echarts; see deploy/nodered/Dockerfile)')";
        msg.headers = { "Content-Type": "application/javascript" };
        return msg;
    }
    body = fs.readFileSync(file, "utf8");
    context.set("body", body);
}
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "public, max-age=86400" };
msg.payload = body;
return msg;

// OFM Report (step R1, ADR-0033): answers the report page. Like the line
// view and the trend page it reads the database only as ofm_screens, through
// the functions of migration 031. Messages from the page (msg._client = that browser):
// - {cmd: "lines"}   the lines that can be reported (config.fn_screen_model)
// - {cmd: "report", req, line, preset, from, to, compare}
//       preset: yesterday | last7 | lastweek | thismonth | lastmonth | custom
//       (custom: from and to are dates YYYY-MM-DD in the site's time zone,
//       both included). The period is worked out here in the site's time
//       zone, so a viewer in another time zone gets the plant's days. The
//       previous period: the month before for a month, else the same length
//       just before. Everything of the report is fetched in parallel.
// Answers go back to that browser only: {topic, payload}. Times are epoch
// milliseconds UTC (ADR-0003); the page shows them in the site's time zone.
const MAX_DAYS = 93;
const pg = global.get("pg");
if (!pg) { node.error("the pg library is not available (see nodered/settings.js)"); return null; }
let pool = context.get("pool");
if (!pool) {
    pool = new pg.Pool({
        host: "timescaledb", port: 5432, database: "ofm", user: "ofm_screens", password: env.get("OFM_SCREENS_DB_PASSWORD"),
        application_name: "ofm-report", max: 6, connectionTimeoutMillis: 5000, statement_timeout: 60000
    });
    pool.on("error", () => { /* reconnects on the next query */ });
    context.set("pool", pool);
}
const client = msg._client && msg._client.socketId ? msg._client : null;
const p = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
if (!client || !p.cmd) return null;
const reply = (topic, payload) => node.send({ topic, payload, _client: client });
const num = x => x === null || x === undefined ? null : Number(x);
const ms = x => x === null || x === undefined ? null : new Date(x).getTime();

// one KPI row of hist.fn_report_kpi as the page wants it
const kpi = r => ({
    key: r.group_key, label: r.label, t0: ms(r.period_start), t1: ms(r.period_end),
    p1: num(r.pos1_s), p2: num(r.pos2_s), p3: num(r.pos3_s), p4: num(r.pos4_s), p5: num(r.pos5_s), p6: num(r.pos6_s), p7: num(r.pos7_s),
    p8: num(r.pos8_s), p9: num(r.pos9_s), p10: num(r.pos10_s), p11: num(r.pos11_s), p12: num(r.pos12_s), p90: num(r.unaccounted_s), p13: num(r.pos13_s),
    run: num(r.running_s), good: num(r.good), reject: num(r.reject),
    a: num(r.availability), p: num(r.performance), q: num(r.quality), oee: num(r.oee), ge: num(r.ge), lu: num(r.lu),
    downtimeH: num(r.downtime_h), over100: r.performance_over_100 === true
});

try {
    if (p.cmd === "lines") {
        const lines = (await pool.query("SELECT config.fn_screen_model() AS m")).rows[0].m || [];
        const rules = lines.length ? (await pool.query(
            "SELECT l AS id, (SELECT has_rule FROM hist.fn_report_summary(l, now(), now())) AS has_rule FROM unnest($1::integer[]) l",
            [lines.map(l => l.id)])).rows : [];
        const hasRule = Object.fromEntries(rules.map(r => [r.id, r.has_rule === true]));
        reply("lines", lines.map(l => ({ id: l.id, name: l.displayName || l.name, hasRule: hasRule[l.id] === true })));
        return null;
    }
    if (p.cmd !== "report") return null;
    const line = Number(p.line);
    if (!Number.isInteger(line) || line <= 0) throw new Error("choose a line");
    const preset = ["yesterday", "last7", "lastweek", "thismonth", "lastmonth", "custom"].includes(p.preset) ? p.preset : "lastmonth";
    const date = s => typeof s === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null;
    if (preset === "custom" && (!date(p.from) || !date(p.to))) throw new Error("type both dates");
    // the period and the previous period, in the site's time zone
    const per = (await pool.query(`
        WITH z AS (SELECT time_zone AS tz FROM hist.fn_report_summary($1, now(), now())),
        d AS (SELECT z.tz, (now() AT TIME ZONE z.tz)::date AS today FROM z),
        r AS (
          SELECT d.tz,
            CASE $2 WHEN 'yesterday' THEN d.today - 1 WHEN 'last7' THEN d.today - 7
                    WHEN 'lastweek' THEN date_trunc('week', d.today)::date - 7 WHEN 'thismonth' THEN date_trunc('month', d.today)::date
                    WHEN 'lastmonth' THEN (date_trunc('month', d.today) - interval '1 month')::date ELSE $3::date END AS d0,
            CASE $2 WHEN 'yesterday' THEN d.today WHEN 'last7' THEN d.today
                    WHEN 'lastweek' THEN date_trunc('week', d.today)::date WHEN 'thismonth' THEN d.today + 1
                    WHEN 'lastmonth' THEN date_trunc('month', d.today)::date ELSE $4::date + 1 END AS d1
          FROM d)
        SELECT r.tz, r.d0::text AS d0, (r.d1 - 1)::text AS dlast, r.d1 - r.d0 AS days,
               extract(epoch FROM r.d0::timestamp AT TIME ZONE r.tz) * 1000 AS t0,
               extract(epoch FROM r.d1::timestamp AT TIME ZONE r.tz) * 1000 AS t1,
               extract(epoch FROM (CASE WHEN $2 IN ('lastmonth', 'thismonth') THEN (r.d0 - interval '1 month')::timestamp
                                        ELSE (r.d0 - (r.d1 - r.d0))::timestamp END) AT TIME ZONE r.tz) * 1000 AS p0
        FROM r`, [line, preset, date(p.from), date(p.to)])).rows[0];
    if (!per || !per.tz) throw new Error("this line has no site time zone");
    const days = Number(per.days);
    if (!(days >= 1)) throw new Error("the end date is before the start date");
    if (days > MAX_DAYS) throw new Error("a report covers at most " + MAX_DAYS + " days");
    const t0 = new Date(Number(per.t0)), t1 = new Date(Number(per.t1)), prevFrom = new Date(Number(per.p0));
    // this month so far: compare with the same length of the month before
    const end = new Date(Math.min(t1.getTime(), Date.now()));
    const prevTo = preset === "thismonth" ? new Date(prevFrom.getTime() + (end.getTime() - t0.getTime())) : t0;
    const compare = p.compare !== false;
    const group = days > 42 ? "week" : "day";
    const q = (sql, args) => pool.query(sql, args).then(r => r.rows);
    const A = [line, t0, t1], B = [line, prevFrom, prevTo];
    const [summary, total, prevTotal, series, losses, orders, products, shifts, machines, prevMachines] = await Promise.all([
        q("SELECT * FROM hist.fn_report_summary($1, $2, $3)", A),
        q("SELECT * FROM hist.fn_report_kpi($1, $2, $3, 'total')", A),
        compare ? q("SELECT * FROM hist.fn_report_kpi($1, $2, $3, 'total')", B) : Promise.resolve([]),
        q("SELECT * FROM hist.fn_report_kpi($1, $2, $3, $4)", [line, t0, t1, group]),
        q("SELECT * FROM hist.fn_report_losses($1, $2, $3)", A),
        q("SELECT * FROM hist.fn_report_orders($1, $2, $3)", A),
        q("SELECT * FROM hist.fn_report_kpi($1, $2, $3, 'product')", A),
        q("SELECT * FROM hist.fn_report_kpi($1, $2, $3, 'shift')", A),
        q("SELECT * FROM hist.fn_report_machines($1, $2, $3)", A),
        compare ? q("SELECT * FROM hist.fn_report_machines($1, $2, $3)", B) : Promise.resolve([])
    ]);
    const s = summary[0] || {};
    const prodName = {};
    for (const o of orders) prodName[o.sku] = o.product;
    const out = {
        req: p.req, preset, group,
        period: { t0: t0.getTime(), t1: t1.getTime(), end: end.getTime(), d0: per.d0, dlast: per.dlast, days,
                  prevT0: compare ? prevFrom.getTime() : null, prevT1: compare ? prevTo.getTime() : null },
        line: { id: line, name: s.line_name, path: s.line_path, tz: s.time_zone, target: num(s.oee_target) },
        flags: { ruleChanged: s.kpi_rule_changed === true, testData: s.test_data === true, hasRule: s.has_rule === true },
        total: total[0] ? kpi(total[0]) : null,
        prev: prevTotal[0] ? kpi(prevTotal[0]) : null,
        series: series.map(kpi),
        losses: losses.map(l => ({ cat: l.loss_category_id, kind: l.kind, reason: l.reason, machine: l.machine, stops: num(l.stops),
                                  s: num(l.seconds), share: num(l.share_of_lost), pts: num(l.oee_points) })),
        orders: orders.map(o => ({ id: o.work_order_id, wo: o.wo_number, sku: o.sku, product: o.product, planned: num(o.planned_qty),
                                  plannedStart: ms(o.planned_start), started: ms(o.started_at), completed: ms(o.completed_at), by: o.started_by,
                                  outside: o.partly_outside === true, durationS: num(o.duration_s), scheduledS: num(o.scheduled_s),
                                  changeoverS: num(o.changeover_s), good: num(o.good), reject: num(o.reject), a: num(o.availability),
                                  p: num(o.performance), q: num(o.quality), oee: num(o.oee), p8: num(o.pos8_s), p13: num(o.pos13_s),
                                  loss: o.biggest_loss, lossS: num(o.biggest_loss_s) })),
        products: products.map(r => Object.assign(kpi(r), { name: prodName[r.label] || r.label })),
        shifts: shifts.map(kpi),
        machines: machines.map(m => ({ id: m.machine_id, name: m.machine, constraint: m.is_constraint === true, chargedS: num(m.charged_s),
                                       breakdowns: num(m.breakdowns), mtbfH: num(m.mtbf_h), mttrMin: num(m.mttr_min) })),
        prevMachines: prevMachines.map(m => ({ id: m.machine_id, breakdowns: num(m.breakdowns), mtbfH: num(m.mtbf_h), mttrMin: num(m.mttr_min) }))
    };
    node.status({ fill: "green", shape: "dot", text: (s.line_name || line) + " · " + per.d0 + " – " + per.dlast + " · " + new Date().toLocaleTimeString() });
    reply("report", out);
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: e.message });
    reply("error", { req: p.req, text: e.message });
}
return null;
